<script setup lang="ts">import { ref, watch } from 'vue';import type { ProviderProfile } from '../api/system';import UiDialog from './ui/UiDialog.vue';import UiButton from './ui/UiButton.vue';import LlmExecutionControl from './LlmExecutionControl.vue';import { useI18nStore } from '../stores/i18n';const props=defineProps<{open:boolean;sourceText:string;proposedText?:string;changes?:string[];warnings?:string[];model?:string;busy?:boolean;profiles:ProviderProfile[];providerProfileId:string;recordId?:string}>();const emit=defineEmits<{close:[];run:[instructions:string,providerProfileId:string];apply:[text:string];"update:providerProfileId":[value:string]}>();const i18n=useI18nStore();const instructions=ref('');const draft=ref('');function reset(){instructions.value='';draft.value=''}watch(()=>props.proposedText,value=>{draft.value=String(value||'')},{immediate:true});watch(()=>[props.open,props.recordId] as const,(value,old)=>{if(value[0]&&(!old?.[0]||value[1]!==old?.[1]))reset()});function run(){if(!props.providerProfileId)return;draft.value='';emit('run',instructions.value,props.providerProfileId)}</script><template><UiDialog :open="open" size="xlarge" :title="i18n.t('pdf_corpus.llm_touchup_title','LLM touch-up')" :description="i18n.t('pdf_corpus.llm_touchup_help','Use an LLM to conservatively correct formatting, punctuation, OCR artifacts, and extraction errata without paraphrasing the text.')" :close-label="i18n.t('ui.close','Close')" @close="emit('close')"><LlmExecutionControl :model-value="providerProfileId" :profiles="profiles" :disabled="busy" :task="i18n.t('pdf_corpus.llm_touchup_provider_help','The selected profile will propose a text correction. Nothing is applied until you approve it.')" @update:model-value="value=>emit('update:providerProfileId',value)"/><div class="touchup-controls"><label><span>{{i18n.t('pdf_corpus.llm_touchup_instruction','Optional instruction')}}</span><input v-model="instructions" class="control" :placeholder="i18n.t('pdf_corpus.llm_touchup_instruction_placeholder','For example: preserve this passage as verse')"></label><UiButton variant="primary" :disabled="busy||!providerProfileId" :label="busy?i18n.t('pdf_corpus.llm_touchup_running','Running touch-up…'):i18n.t('pdf_corpus.run_llm_touchup','Run LLM touch-up')" @click="run"/></div><p v-if="model" class="model-note">{{i18n.tf('pdf_corpus.llm_touchup_model','Proposal generated by {model}',{model})}}</p><div v-if="proposedText" class="touchup-grid"><section><h3>{{i18n.t('pdf_corpus.cleanup_before','Before')}}</h3><pre>{{sourceText}}</pre></section><section><h3>{{i18n.t('pdf_corpus.llm_touchup_proposed','LLM proposal')}}</h3><textarea v-model="draft" :aria-label="i18n.t('pdf_corpus.llm_touchup_proposed','LLM proposal')"></textarea></section></div><div v-if="changes?.length||warnings?.length" class="touchup-notes"><section v-if="changes?.length"><h3>{{i18n.t('pdf_corpus.llm_touchup_changes','Reported changes')}}</h3><ul><li v-for="item in changes" :key="item">{{item}}</li></ul></section><section v-if="warnings?.length"><h3>{{i18n.t('pdf_corpus.llm_touchup_warnings','Warnings')}}</h3><ul><li v-for="item in warnings" :key="item">{{item}}</li></ul></section></div><template #footer><span class="footer-note">{{i18n.t('pdf_corpus.llm_touchup_source_preserved','Applying the proposal changes reviewed text only. The immutable extracted source remains preserved.')}}</span><div><UiButton :label="i18n.t('ui.cancel','Cancel')" @click="emit('close')"/><UiButton v-if="proposedText" variant="primary" :disabled="!draft.trim()||busy" :label="i18n.t('pdf_corpus.apply_llm_touchup','Apply proposal to draft')" @click="emit('apply',draft)"/></div></template></UiDialog></template><style scoped>.touchup-controls{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:end;margin-top:14px}.touchup-controls label{display:grid;gap:5px;font-size:.875rem;font-weight:700}.control{min-height:42px}.model-note,.footer-note{font-size:.8125rem;color:var(--muted)}.touchup-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.touchup-grid h3,.touchup-notes h3{font-size:.9375rem;margin:0 0 6px}.touchup-grid pre,.touchup-grid textarea{box-sizing:border-box;width:100%;height:360px;margin:0;overflow:auto;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--soft);white-space:pre-wrap;font:15px/1.6 Georgia,serif}.touchup-grid textarea{resize:vertical;background:var(--card);color:var(--text)}.touchup-notes{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.touchup-notes section{padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--soft);font-size:.875rem;line-height:1.45}.touchup-notes ul{margin:0;padding-inline-start:20px}.touchup-controls :focus-visible,.touchup-grid textarea:focus-visible{outline:3px solid var(--accent);outline-offset:2px}@media(max-width:760px){.touchup-controls,.touchup-grid,.touchup-notes{grid-template-columns:1fr}.touchup-grid pre,.touchup-grid textarea{height:260px}}</style>